param([string]$ProjectRoot = (Split-Path -Parent $PSScriptRoot))
$ErrorActionPreference='Stop'
$issues=[System.Collections.Generic.List[string]]::new()
$build=Get-Content -LiteralPath (Join-Path $ProjectRoot 'build/app.js') -Raw -Encoding UTF8
$index=Get-Content -LiteralPath (Join-Path $ProjectRoot 'index.html') -Raw -Encoding UTF8
$css=Get-Content -LiteralPath (Join-Path $ProjectRoot 'app.css') -Raw -Encoding UTF8
$order=Get-Content -LiteralPath (Join-Path $ProjectRoot 'SOURCE_ORDER.txt') -Encoding UTF8
$genre=Get-Content -LiteralPath (Join-Path $ProjectRoot 'src/data/genre-relations.js') -Raw -Encoding UTF8
$i18nSource=Get-Content -LiteralPath (Join-Path $ProjectRoot 'src/data/i18n.js') -Raw -Encoding UTF8
$playerVisualsSource=Get-Content -LiteralPath (Join-Path $ProjectRoot 'src/ui/player-visuals.js') -Raw -Encoding UTF8
$governance=Get-Content -LiteralPath (Join-Path $ProjectRoot 'MODULE_GOVERNANCE.md') -Raw -Encoding UTF8
$eventContracts=Get-Content -LiteralPath (Join-Path $ProjectRoot 'EVENT_CONTRACTS.md') -Raw -Encoding UTF8
$librarySource=Get-Content -LiteralPath (Join-Path $ProjectRoot 'src/services/library-runtime.js') -Raw -Encoding UTF8
$queueSource=Get-Content -LiteralPath (Join-Path $ProjectRoot 'src/services/queue-runtime.js') -Raw -Encoding UTF8
$playbackSource=Get-Content -LiteralPath (Join-Path $ProjectRoot 'src/services/playback-runtime.js') -Raw -Encoding UTF8
$neuralSource=Get-Content -LiteralPath (Join-Path $ProjectRoot 'src/services/neural-runtime.js') -Raw -Encoding UTF8
$bootstrapSource=Get-Content -LiteralPath (Join-Path $ProjectRoot 'src/bootstrap/main.js') -Raw -Encoding UTF8
$historySource=Get-Content -LiteralPath (Join-Path $ProjectRoot 'src/services/history-service.js') -Raw -Encoding UTF8
$pipSource=Get-Content -LiteralPath (Join-Path $ProjectRoot 'src/services/pip-runtime.js') -Raw -Encoding UTF8
$spatialSource=Get-Content -LiteralPath (Join-Path $ProjectRoot 'src/engines/spatial-engine.js') -Raw -Encoding UTF8
$spatialPresetSource=Get-Content -LiteralPath (Join-Path $ProjectRoot 'src/data/spatial-presets.js') -Raw -Encoding UTF8
$eqSource=$spatialSource
$agents=Get-Content -LiteralPath (Join-Path $ProjectRoot 'AGENTS.md') -Raw -Encoding UTF8
$currentState=Get-Content -LiteralPath (Join-Path $ProjectRoot 'CURRENT_STATE.md') -Raw -Encoding UTF8
$runtimeConstantsSource=Get-Content -LiteralPath (Join-Path $ProjectRoot 'src/core/runtime-constants.js') -Raw -Encoding UTF8
$spectrumSource=Get-Content -LiteralPath (Join-Path $ProjectRoot 'src/engines/bionic-engine.js') -Raw -Encoding UTF8
$audioSource=Get-Content -LiteralPath (Join-Path $ProjectRoot 'src/engines/audio-engine.js') -Raw -Encoding UTF8
$settingsSource=Get-Content -LiteralPath (Join-Path $ProjectRoot 'src/ui/settings-view.js') -Raw -Encoding UTF8
$soundSource=Get-Content -LiteralPath (Join-Path $ProjectRoot 'src/ui/sound-view.js') -Raw -Encoding UTF8
$fileAdapterSource=Get-Content -LiteralPath (Join-Path $ProjectRoot 'src/adapters/browser/file-adapter.js') -Raw -Encoding UTF8
$sharedControlsSource=Get-Content -LiteralPath (Join-Path $ProjectRoot 'src/ui/shared-controls.js') -Raw -Encoding UTF8
$changelogSource=Get-Content -LiteralPath (Join-Path $ProjectRoot 'src/ui/changelog-view.js') -Raw -Encoding UTF8
$releasesSource=Get-Content -LiteralPath (Join-Path $ProjectRoot 'src/data/releases.js') -Raw -Encoding UTF8
$galaxySource=if(Test-Path -LiteralPath (Join-Path $ProjectRoot 'src/services/galaxy-runtime.js')){Get-Content -LiteralPath (Join-Path $ProjectRoot 'src/services/galaxy-runtime.js') -Raw -Encoding UTF8}else{''}
$galaxyViewSource=if(Test-Path -LiteralPath (Join-Path $ProjectRoot 'src/ui/galaxy-view.js')){Get-Content -LiteralPath (Join-Path $ProjectRoot 'src/ui/galaxy-view.js') -Raw -Encoding UTF8}else{''}
$visualMotionFiles=@(
  'src/ui/shared-controls.js','src/ui/player-visuals.js','src/ui/changelog-view.js',
  'src/services/playback-runtime.js','src/services/pip-runtime.js','src/services/queue-runtime.js',
  'src/engines/spatial-engine.js'
)
$visualMotionSource=($visualMotionFiles | ForEach-Object {Get-Content -LiteralPath (Join-Path $ProjectRoot $_) -Raw -Encoding UTF8}) -join "`n"

function Expect([bool]$condition,[string]$message){if(!$condition){$issues.Add($message)}}
Expect (($build -split 'window\.GPModules \?\?=').Count-1 -eq 1) 'Module Registry must be created once'
Expect (($build -split 'const playlist = \[\]').Count-1 -eq 1) 'playlist implementation must occur once'
Expect (($build -split 'const playQueue = \[\]').Count-1 -eq 1) 'playQueue implementation must occur once'
Expect (($build -split 'const deckA = new Audio\(\)').Count-1 -eq 1 -and ($build -split 'const deckB = new Audio\(\)').Count-1 -eq 1) 'exactly one Deck A and one Deck B expected'
Expect (($build -split 'new AudioContextConstructor').Count-1 -eq 2 -and $build -match 'latencyHint:"playback"' -and $librarySource -notmatch 'spectrumDecodeCtx|ensureSpectrumDecodeCtx|new\s+\(window\.AudioContext' -and $librarySource -match 'await decodeAudioBuffer\(arrayBuffer\)') 'Playback and analysis must share the Audio Engine context with one compatibility fallback'
Expect ($build -notmatch '\bwindow\.currentIndex\b') 'window.currentIndex is forbidden'
Expect ($build -notmatch '(?m)^\s*(import|export)\s') 'ES module syntax is forbidden'
Expect ($index -match '<link rel="stylesheet" href="\./app\.css\?v=7\.6\.3-r1">' -and $index -match '<script src="\./build/app\.js\?v=7\.6\.3-r1"></script>') 'index must load the 7.6.3 CSS and build/app.js cache revision'
Expect ($index -notmatch '<script src="\./app\.js"></script>') 'index must not load baseline app.js'
Expect ($index -match '<title>Glass Player</title>') 'HTML version mismatch'
Expect ($spectrumSource -match 'const GP=window\.GP=\{[\s\S]*?generation:7,[\s\S]*?version:"7\.6\.3"') 'early analyzer facade version mismatch'
Expect ($build -match 'architecture:"Peregrine Lake"') 'architecture mismatch'
Expect ($build -match 'core:"GP Core 4\.3 \u2014 Kinetic Runtime"') 'Core version mismatch'
Expect ($index -match 'id="buildBadgeBtn">HOTFIX BUILD</button>') 'current release name missing'
Expect ($bootstrapSource -match 'Object\.freeze\(\{generation:7,version:"7\.6\.3"') 'public facade not frozen'
Expect ($build -match 'motion:"GP Motion Engine 4\.2 \u2014 Kinetic Motion"') 'Motion Engine version mismatch'
Expect ($build -match 'const GP_MOTION_TARGET_FPS = 120' -and $build -match 'refreshRateCeiling:GP_MOTION_TARGET_FPS' -and $build -match 'scheduler:"requestAnimationFrame"' -and $build -match 'fixedFrameTimers:false') '120Hz Motion contract missing from Core runtime'
Expect ($visualMotionSource -notmatch 'setInterval\s*\(' -and $visualMotionSource -notmatch '1000\s*/\s*60|16\.6(?:6+)?') 'Visual motion must not use fixed 60Hz frame timers'
Expect ($governance -match 'all visual motion must use CSS transitions/animations' -and $governance -match 'Web Animations API' -and $governance -match 'requestAnimationFrame' -and $governance -match 'up to 120 Hz' -and $eventContracts -match 'Visual Motion Scheduling Contract') '120Hz Motion contract missing from governance documents'
Expect ($spectrumSource -match 'spectrum:`GP Spectrum Engine \$\{GP_SPECTRUM_ENGINE_VERSION\} \u2014 Signal`' -and $bootstrapSource -match 'spectrum:`GP Spectrum Engine \$\{GP_SPECTRUM_ENGINE_VERSION\} \u2014 Signal`') 'Spectrum Engine version must use the centralized visible constant'
Expect ($build -match 'window\.GP=publicFacade') 'window.GP must publish the read-only facade'
Expect (-not (Test-Path -LiteralPath (Join-Path $ProjectRoot 'src/js'))) 'src/js still exists'
Expect (-not (Test-Path -LiteralPath (Join-Path $ProjectRoot 'src/modules'))) 'src/modules still exists'
Expect (($order | Where-Object {$_ -eq 'src/bootstrap/main.js'}).Count -eq 1) 'bootstrap/main.js must occur once'
Expect (($order.IndexOf('src/core/runtime-constants.js') -ge 0) -and ($order.IndexOf('src/core/runtime-constants.js') -lt $order.IndexOf('src/engines/audio-engine.js')) -and ($order.IndexOf('src/core/runtime-constants.js') -lt $order.IndexOf('src/engines/bionic-engine.js')) -and ($order.IndexOf('src/core/runtime-constants.js') -lt $order.IndexOf('src/bootstrap/main.js'))) 'runtime constants must precede Audio, Spectrum and Bootstrap consumers'
Expect (($order | Where-Object {$_ -eq 'src/data/genre-relations.js'}).Count -eq 1) 'genre-relations.js must occur once'
Expect ($genre -match 'source:"offline-static"') 'genre graph must declare offline-static source'
Expect ($genre -notmatch '\bfetch\s*\(|XMLHttpRequest|WebSocket|EventSource') 'genre graph must not perform runtime network I/O'
Expect ($build -match 'const NEURAL_MIN_CONFIDENCE=\.70') 'Neural confidence gate must be 0.70'
Expect ($bootstrapSource -match 'genreRelations:GP\.genreRelations' -and $bootstrapSource -notmatch 'createGalaxyService|createGalaxyView' -and $neuralSource -match 'function dailyFeatureSimilarity' -and $neuralSource -notmatch 'Galaxy|recommendationSimilarity') 'Neural and the public facade must keep local similarity plus the Genre Relations edge without Galaxy'
Expect ($build -match 'normalizationGainDb') 'Spectrum loudness normalization cache field missing'
Expect ($index -match 'id="loudnessNormalizeToggle"') 'Loudness normalization control missing'
Expect ($index -match 'id="loudnessInfoBtn"') 'Loudness information control missing'
Expect ($css -match 'gpImportPlusWave642') 'Import-file motion missing'
Expect ($css -match 'gpFolderPaper644') 'Import-folder motion missing'
Expect (($index -split 'class="scan-cycle-icon"').Count-1 -eq 2) 'Import and rescan must share two centered scan icons'
Expect ($css -match 'gpScanCycle644' -and $build -match 'classList\.add\("is-scanning"\)') 'Active import/rescan rotation contract missing'
Expect ($build -match 'if\(pop\.classList\.contains\("show"\)\)return;playMotion\(\);show\(\)') 'Open Sound information popover must ignore repeated button clicks'
Expect ($build -match 'crossfadeSlider"\)\.disabled=!crossfadeEnabled') 'Disabled Crossfade must disable its duration slider'
Expect ($build -match 'eqHeadroomGain' -and $build -match 'function combinedEQPeakDb' -and $build -match 'outputLimiterBypass = audioCtx\.createGain\(\)') 'Measured EQ headroom or linear final output path missing'
Expect ($build -match 'rect\.width<2\|\|rect\.height<2' -and $build -match 'miniEqGeometry=null;drawMiniEq\(\);syncMiniEqMeter\(\)') 'Hidden mini EQ geometry recovery missing'
Expect ($build -match 'matches\(":disabled,\.toggle-switch"\)') 'Toggle switches must bypass global press scaling'
Expect ($css -match 'gpScanCycle644 1\.35s linear infinite') 'Import/rescan rotation speed mismatch'
Expect ($build -match '"6\.5\.0":"EXPERIENCE UPDATE') '6.5.0 bilingual release summary missing'
Expect ($build -match 'GP_MOTION_TARGET_FPS\s*=\s*120' -and $build -match 'GP_PIP_TARGET_FPS\s*=\s*30' -and $build -notmatch 'captureStream\(GP_MOTION_TARGET_FPS\)') 'Shared 120Hz motion ceiling or isolated 30Hz PiP budget missing'
Expect ($build -match 'function runPlaybackMotion120' -and $build -match 'GP_MOTION_FRAME_MS') '120Hz playback progress loop missing'
Expect ($css -notmatch 'steps\(4,end\)' -and $css -notmatch '\.blob\{[^}]*will-change') 'Low-frame feedback or persistent blob GPU layer remains'
Expect ($build -match '"6\.5\.1":"MOTION UPDATE') '6.5.1 bilingual release summary missing'
Expect ($index -match 'id="ambientCanvas"' -and $index -match 'id="ambientCanvasNext"' -and $css -match '#ambientGlow\{\s*display:none!important;\s*\}' -and $css -notmatch '#ambientGlow\{[^}]*filter:' -and $css -match '\.ambient-blur-layer\{\s*display:none!important;\s*\}') 'Static ambient raster surfaces or CSS-filter bypass missing'
Expect ($build -match 'function drawAmbientPalette' -and $build -match 'function drawAmbientCover' -and $build -match 'const metrics=ambientRasterMetrics\(\)' -and $build -match 'sampleWidth=384' -and $build -match 'blur\(28px\)' -and $css -match 'transform:none!important;[\s\S]*?filter:none!important;[\s\S]*?image-rendering:auto') 'Native-pixel low-frequency ambient field contract missing'
Expect ($build -match '"6\.5\.2":"HOTFIX BUILD') '6.5.2 bilingual release summary missing'
