Expect ($build -match 'function syncCurrentTrackPlaybackIndicator' -and $build -notmatch 'if\(changed\|\|forceRender\)render\(searchInputSafe\(\)\)') 'Playback state must not rebuild the Library and Queue during turntable motion'
