Expect ($build -match 'deckA\.preload = "auto"' -and $build -match 'deckB\.preload = "auto"') 'Both playback Decks must preload local audio'
Expect ($build -match 'standby\.play\(\)\.then\(\(\)=>\{' -and $build -match 'const fadeNow=audioCtx\.currentTime' -and $build -notmatch 'crossfading=false;decks\.forEach\(deck=>deck\.pause\(\)\);\s*if\(audioCtx\)') 'Decoder-ready transition or pause-before-fade regression'
Expect ($build -match 'outputTrim\.connect\(outputGain\)' -and $build -notmatch 'outputTrim\.connect\(safety\)' -and $build -notmatch 'spatial\.output\.connect\(outputLimiterBypass\)') 'Delayed compressor paths must remain outside continuous playback'
Expect ($build -match 'function scheduleHistoryPersistence' -and $build -match 'flushHistory\(true\)' -and $build -match 'persistHistoryStoreNow') 'Idle-batched listening history persistence contract missing'
Expect ($build -match 'if\(isPlaying\|\|wantsPlayback\)\{setTimeout\(waitUntilPlaybackIsIdle,700\);return;\}') 'Spectrum analysis must yield completely while music is playing'
Expect ($build -match 'version:"6\.5\.4"') '6.5.4 runtime version missing'
Expect ($build -match '"6\.5\.4":"HOTFIX BUILD') '6.5.4 English release summary missing'
Expect ($index -match 'id="currentVersionBtn"[^>]*>[^<]*7\.6\.3[^<]*HOTFIX BUILD</button>') '7.6.3 current-version label missing'
Expect ($css -match '\.build-card\{[^}]*border:1px solid var\(--accent\)' -and $css -match '\.build-card::after\{\s*content:none') 'Build card must use one real Accent border'
Expect ($build -match 'requestAnimationFrame\(\(\)=>\{position\(\);requestAnimationFrame\(position\);\}\)') 'Sound information portals must position after visibility commits'
Expect ($build -match 'await renderLibraryIncrementally\(searchInputSafe\(\)\);\s*if\(currentIndex===-1&&playlist\.length>0\)') 'First import must finish frame-yielding Library render before selecting its initial track'
Expect ($build -match 'queuePositionPending=true' -and $build -match 'finalTab==="queue"&&!manualQueueActive') 'Hidden Queue current-track alignment contract missing'
Expect ($build -match 'preampDb=-combinedPeakDb' -and $build -match 'getFrequencyResponse\(eqResponseFrequencies' -and $build -match 'finalOutputTrimGain\.gain\.value=Math\.pow\(10,-1\.5/20\)' -and $build -match 'outputLimiterBypass\.connect\(masterGain\)') 'Measured final -1.5dBFS single-path output budget missing'
Expect (($build -split 'createMediaElementSource').Count-1 -eq 1 -and ($build -split 'new AudioContextConstructor').Count-1 -eq 2) 'Audio graph initialization must remain singular with one constructor fallback'
Expect ($build -match '__GP_AUDIO_DIAGNOSTICS__' -and $build -match 'monoAveragePeak' -and $build -match 'unsafeRawSumPeak' -and $build -match 'firstExceed') 'Audio first-exceed and mono-fold diagnostics missing'
