Expect ($build -match 'miniEqLastSample>=42' -and $build -match 'Math\.pow\(rms,\.72\)\*\.86' -and $build -match 'timeConstant=difference>0\?\.075:\.18' -and $build -notmatch 'Math\.round\(raw/\.035\)\*\.035' -and $build -notmatch 'Math\.round\(Math\.max\(\.16,Math\.min\(1,level\)\)\*height\)') 'Visible-amplitude continuous four-band meter motion missing'
Expect ($build -match 'qualifiedPeriods=.*slice\(0,3\)' -and $build -match 'preference\?\.timeGenre') 'Multi-period Neural listening rhythm contract missing'
Expect ($releasesSource -match 'version:"7\.3\.0"' -and $releasesSource -match '"7\.3\.0":"HOTFIX BUILD' -and $releasesSource -match '"7\.2\.2":"HOTFIX BUILD' -and $releasesSource -match '"7\.2\.1":"HOTFIX BUILD' -and $releasesSource -match '"7\.2\.0":"VISIONAL UPDATE' -and $releasesSource -match '"7\.1\.1":"STABILITY UPDATE' -and $releasesSource -match '"7\.1\.0":"RESIZE UPDATE' -and $releasesSource -match '"7\.0\.2":"HOTFIX BUILD' -and $releasesSource -match '"7\.0\.1":"HOTFIX BUILD' -and $releasesSource -match '"7\.0\.0":"GALAXY UPDATE' -and $releasesSource -match '"6\.7\.1":"HOTFIX BUILD' -and $releasesSource -match '"6\.7\.0":"LOGIC UPDATE' -and $releasesSource -match '"6\.6\.5":"SPECTRUM UPDATE' -and $releasesSource -match '"6\.6\.0":"SNOW LEOPARD 3\.0' -and $releasesSource -match 'Interface and Scrolling') '7.3.0 bilingual release history missing'
Expect ($build -match 'entry\.dailyPlays\[day\]=\(entry\.dailyPlays\[day\]\|\|0\)\+1' -and $build -match 'function sumPlayCountRange' -and $build -match 'function getLibraryPlayCounts' -and $build -match 'counts\.set\(track\.id,entry\?sumPlayCountRange') 'Calendar-range daily play-count persistence missing'
Expect ($build -match 'progressRatio=duration\?behaviorRuntime\.listened/duration:0' -and $build -match 'ratio=behaviorRuntime\.listened/audio\.duration' -and $build -match 'progressRatio<\.75' -and $build -match 'ratio>=\.75' -and $build -match 'playCounted:true|playCounted=false|playCounted:false') '75 percent cumulative-play threshold or duplicate guard missing'
Expect ($build -match 'legacyUndatedPlayCount' -and $build -match 'legacyDailySeconds' -and $build -match 'Math\.round\(legacy\*rangeSeconds/allLegacySeconds\)') 'Legacy lifetime play counts are not restored into selected date ranges'
Expect ($build -match 'const inferLegacy=seconds=>\{' -and $build -match 'if\(duration>0\)return Math\.max\(1,Math\.floor\(listened/\(duration\*\.75\)\)\)' -and $build -match 'return 1;' -and $build -match 'entry\.duration=Number\(t\.duration\)') 'Zero-count legacy history is not reconstructed from daily listened seconds and track duration'
Expect ($build.Contains('const signature=`${uiLanguage}:${playlist.length}:')) 'Queue cache signature must include the active interface language'
Expect ($bootstrapSource -match 'fusion:`GP Fusion Engine \$\{GP_FUSION_ENGINE_VERSION\} \u2014 Playlist Flow`' -and $build -match 'motion:"GP Motion Engine 4\.2 \u2014 Kinetic Motion"') 'Current Fusion or Motion engine version missing'
Expect ($index -match 'id="eqCurveLine"' -and $index -match 'id="eqPresetPop"' -and $index -notmatch 'data-p="classical"' -and $index -notmatch 'data-p="podcast"') 'Curve EQ markup or removed presets contract missing'
