Expect ($build -match 'const curvePath=monotoneCurvePath\(points,\.62\)' -and $build -match 'function monotoneCurvePath\(points,tension=\.62\)' -and $build -match 'class="chart-line" d=') 'Monotone listening-history curve missing'
Expect ($build -match 'const integerDivisor=1' -and $build -match 'outgoing\.classList\.add\("is-visible","is-blending"\)' -and $build -match 'void incoming\.offsetWidth' -and $css -match 'transform:none!important;\s*filter:none!important') 'Precomposed native-pixel 4K ambient crossfade contract missing'
Expect (($index -split '<line x1="').Count-1 -ge 7 -and $css -match '\.eq-grid-lines line') 'Seven-band vertical EQ grid missing'
Expect ($index -notmatch 'id="eqManualState"' -and $index -notmatch '>手动调节</div>') 'Redundant Manual Control caption remains'
Expect ($css -match '\.gp-motion-popover\{\s*display:none;\s*background:var\(--gp-popover-surface\)!important;[\s\S]*?backdrop-filter:var\(--gp-popover-blur\)!important' -and $css -notmatch '\.eq-preset-pop\.gp-motion-popover\{' -and $css -notmatch 'blur\(12px\) saturate\(104%\)') 'System-wide Snooze popover material or EQ override removal missing'
Expect ($css -notmatch '\.nav-item:hover\{\s*background:' -and $css -notmatch '\.release-button:hover\{\s*background:' -and $css -notmatch '\.track-item:hover\{\s*background:' -and $css -notmatch '\.eq-preset-pop button:hover\{\s*background:' -and $css -match '\.nav-item:hover:not\(\.active\) \.single-alpha-icon' -and $css -match '\.chart-dot:hover') 'Hover preselection masks remain or hover motion feedback was removed'
Expect ($build -match 'data-i="\$\{index\}" r="4\.2"' -and $css -match 'fill:color-mix\(in srgb,var\(--accent\) 38%,transparent\)' -and $css -match 'transform:scale\(1\.08\)') 'Small translucent EQ control points missing'
