Expect ($css -match '\.eq-curve-stage\{[^}]*height:(2[5-9][0-9]|[3-9][0-9]{2})px' -and $css -match 'eq-bands' -and $css -match 'eq-curve-visual') 'EQ curve and band controls must have an expanded aligned vertical geometry'
Expect ($css -match 'settings-content \.spatial-modes[^}]*width:(max-content|fit-content|auto)' -and $css -notmatch 'settings-content \.spatial-modes\{[^}]*width:100%') 'Spatial mode strip must end at its last option instead of extending to the screen edge'
Expect ($soundSource -notmatch 'estimated|\u4F30\u7B97|\u4F30\u8BA1' -and $soundSource -match 'infoBitrate') 'Track information bitrate must not show estimated wording'
Expect ($index -match 'id="defaultFolderBtn"' -and $index -match 'id="defaultFolderHint"' -and $settingsSource -match 'defaultFolderBtn' -and $bootstrapSource -match 'chooseDefaultMusicFolder') 'Settings must expose the persisted default Music folder command'
Expect ($bootstrapSource -notmatch 'restoreRememberedAudioFolder') 'Opening the app must not auto-import the remembered default folder'

# 7.4.0 collection, annual report, lossless badge and font contracts
Expect ($index -match 'id="playlistBtn"' -and $index -match 'id="playlistPop"' -and $index -match 'id="playlistNameInput"' -and $index -match 'id="collectionBar"' -and $index -match 'id="rowPlaylistPop"') 'Library playlist switcher, collection bar and row picker must exist'
Expect ($queueSource -match 'USER_PLAYLISTS_RECORD_ID="userPlaylists"' -and $queueSource -match 'function toggleLike' -and $queueSource -match 'function collectionTrackIndices' -and $queueSource -match 'track-like' -and $neuralSource -match 'if\(type==="like"\)') 'Queue-owned playlists and like signals must exist without a new store'
Expect ($index -match 'id="annualReportBtn"' -and $index -match 'id="annualReportModal"' -and $index -match 'id="annualDownloadBtn"' -and $historySource -match 'function buildAnnualReport' -and $historySource -match 'function annualReportWindow' -and $historySource -match 'function downloadAnnualReport') 'History annual report surface, window gate and download must exist'
Expect ($index -match 'id="nowFormatTag"' -and $index -match 'now-title-row' -and $playerVisualsSource -match 'function syncNowFormatTag' -and $css -match '\.now-format-tag') 'Player lossless badge must sit inline on the title row without touching the title marquee'
Expect ($settingsSource -match 'function verifyFontAvailable' -and $settingsSource -match 'document\.fonts\?\.check' -and $settingsSource -match 'dataset\.available') 'Font switching must report missing families instead of failing silently'
Expect ($sharedControlsSource -match '#annualReportBody' -and $sharedControlsSource -match 'annualReportBody:"\.annual-report-dialog"') 'Annual report body must join the shared Soft Scroll Edge contract'

if($issues.Count){'FAIL';$issues|ForEach-Object{"- $_"};exit 1}
'PASS'
"Contracts checked: 266"
exit 0


